"use client";

import { useMemo, useState } from "react";
import { projects, type ProjectTag } from "@/content/site";
import { Section } from "@/components/ui/Section";
import { Reveal } from "@/components/ui/Reveal";

const ALL = "All work" as const;

const tagStyles: Record<ProjectTag, string> = {
  "Requirement Analysis": "bg-teal-soft text-teal-deep",
  Development: "bg-yellow-soft text-ink",
  Database: "bg-coral-soft text-coral",
  Testing: "bg-cream-deep text-muted",
};

export function Work() {
  const [filter, setFilter] = useState<ProjectTag | typeof ALL>(ALL);

  const filters = useMemo(() => {
    const seen: ProjectTag[] = [];
    for (const project of projects) {
      for (const tag of project.tags) {
        if (!seen.includes(tag)) seen.push(tag);
      }
    }
    return [ALL, ...seen] as const;
  }, []);

  const visible =
    filter === ALL ? projects : projects.filter((p) => p.tags.includes(filter));

  return (
    <Section
      id="work"
      eyebrow="Selected work"
      title="My latest works"
      intro="Government registries, university platforms, and non-profit systems — each one shipped with a different slice of my involvement."
    >
      {/* Filter rail */}
      <div className="no-scrollbar -mx-6 mb-10 flex gap-2 overflow-x-auto px-6 sm:mx-0 sm:flex-wrap sm:px-0">
        {filters.map((tag) => {
          const active = filter === tag;
          const count =
            tag === ALL
              ? projects.length
              : projects.filter((p) => p.tags.includes(tag)).length;

          return (
            <button
              key={tag}
              type="button"
              onClick={() => setFilter(tag)}
              aria-pressed={active}
              className={`shrink-0 rounded-full border px-5 py-2.5 text-sm font-medium transition-colors ${
                active
                  ? "border-ink bg-ink text-cream"
                  : "border-line bg-paper text-ink hover:border-teal hover:text-teal-deep"
              }`}
            >
              {tag}
              <span className={active ? "ml-2 text-cream/60" : "ml-2 text-muted"}>
                {count}
              </span>
            </button>
          );
        })}
      </div>

      <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
        {visible.map((project, i) => (
          <Reveal key={project.name} delay={Math.min(i, 5) * 0.05}>
            <article className="flex h-full flex-col rounded-3xl border border-line bg-paper p-6 transition-transform duration-300 hover:-translate-y-1">
              <p className="text-xs font-semibold uppercase tracking-[0.16em] text-coral">
                {project.client}
              </p>
              <h3 className="mt-3 font-display text-2xl font-semibold leading-tight text-ink">
                {project.name}
              </h3>
              {project.full && (
                <p className="mt-1 text-sm italic text-muted">{project.full}</p>
              )}
              <p className="mt-3 flex-1 text-sm leading-relaxed text-muted">
                {project.description}
              </p>
              <ul className="mt-5 flex flex-wrap gap-2">
                {project.tags.map((tag) => (
                  <li
                    key={tag}
                    className={`rounded-full px-3 py-1 text-xs font-medium ${tagStyles[tag]}`}
                  >
                    {tag}
                  </li>
                ))}
              </ul>
            </article>
          </Reveal>
        ))}
      </div>
    </Section>
  );
}
